import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"万族谱系总览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/50-万族谱系总览.md","filePath":"zh/50-万族谱系总览.md","lastUpdated":1789183869000}'),i={name:"zh/50-万族谱系总览.md"};function n(e,t,d,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="万族谱系总览" tabindex="-1">万族谱系总览 <a class="header-anchor" href="#万族谱系总览" aria-label="Permalink to &quot;万族谱系总览&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>50</td></tr><tr><td>所属模块</td><td>种族与生命形态</td></tr><tr><td>核心关键词</td><td>万族、谱系分类、共生关系、种族平等、生命多样性</td></tr></tbody></table><h2 id="一、万族概念的界定" tabindex="-1">一、万族概念的界定 <a class="header-anchor" href="#一、万族概念的界定" aria-label="Permalink to &quot;一、万族概念的界定&quot;">​</a></h2><p>在万灵衡锚本源宙（衡元宙）中，&quot;万族&quot;并非确指一万个种族，而是对宇宙中一切具备感知能力与进化潜能的生命形态的统称。万族概念的核心在于承认生命形态的无限多样性，以及每一种生命形态在共生进化体系中的独特价值。</p><p>锚点共生文明确立&quot;万族平等&quot;的根本原则：一切生命形态，无论其种族起源、生理结构、修为高低、文明程度，在法律面前一律平等，都享有共生宪法赋予的基本权利。这一原则是对掠夺式宇宙观中&quot;强者通吃、弱者消亡&quot;逻辑的根本否定。</p><h2 id="二、万族谱系分类体系" tabindex="-1">二、万族谱系分类体系 <a class="header-anchor" href="#二、万族谱系分类体系" aria-label="Permalink to &quot;二、万族谱系分类体系&quot;">​</a></h2><p>衡元宙的万族按照生命形态的本质特征，分为五大谱系，各谱系之下再细分具体种族：</p><table tabindex="0"><thead><tr><th>谱系</th><th>名称</th><th>本质特征</th><th>代表种族</th></tr></thead><tbody><tr><td>第一谱系</td><td>碳基物质族</td><td>以碳元素为生命基础、以物质身体为主要存在形式的生命</td><td>人族、兽族、鳞族、羽族、木族</td></tr><tr><td>第二谱系</td><td>能量凝聚族</td><td>以能量凝聚为主要存在形式、物质身体为辅或无的生命</td><td>灵族、火族、水族、风族、雷族</td></tr><tr><td>第三谱系</td><td>机械构造族</td><td>以机械构造为身体、以意识核心为生命本质的生命</td><td>机族、械族、数族、晶族</td></tr><tr><td>第四谱系</td><td>意识信息族</td><td>以意识与信息为主要存在形式、可脱离物质载体的生命</td><td>梦族、影族、念族、魂族</td></tr><tr><td>第五谱系</td><td>混合变异族</td><td>由两种或多种谱系生命融合、变异产生的新生命形态</td><td>半兽族、妖灵族、人机族、双魂体</td></tr></tbody></table><p>五大谱系的划分并非绝对隔离，随着共生进化的推进，跨谱系融合与变异的情况日益增多，第五谱系&quot;混合变异族&quot;的规模持续扩大。</p><h2 id="三、主要种族简介" tabindex="-1">三、主要种族简介 <a class="header-anchor" href="#三、主要种族简介" aria-label="Permalink to &quot;三、主要种族简介&quot;">​</a></h2><h3 id="一-碳基物质族" tabindex="-1">（一）碳基物质族 <a class="header-anchor" href="#一-碳基物质族" aria-label="Permalink to &quot;（一）碳基物质族&quot;">​</a></h3><ul><li><strong>人族</strong>：衡元宙中分布最广、适应性最强的种族之一，以其强大的学习能力、社会协作能力与进化潜力著称。人族是锚点共生文明的发起种族之一，在文明治理中扮演重要角色。</li><li><strong>兽族</strong>：具有动物形态特征的种族，体能与感官通常优于人族，部分兽族具有特殊的天赋能力。兽族内部又分为狼族、虎族、熊族、狐族等数十个支系。</li><li><strong>鳞族</strong>：具有鳞片覆盖身体的种族，多生活在水域或潮湿环境，部分鳞族具有水下呼吸与控水能力。龙族是鳞族中最强大的支系。</li><li><strong>羽族</strong>：具有羽翼的种族，以飞行能力著称，多生活在高空或山地环境。羽族内部又分为鹰族、鹤族、蝶族等支系。</li><li><strong>木族</strong>：以植物形态为主要特征的种族，生命悠长，与自然环境高度共生，部分木族具有操控植物与治愈能力。</li></ul><h3 id="二-能量凝聚族" tabindex="-1">（二）能量凝聚族 <a class="header-anchor" href="#二-能量凝聚族" aria-label="Permalink to &quot;（二）能量凝聚族&quot;">​</a></h3><ul><li><strong>灵族</strong>：由天地灵气凝聚而成的生命，形态可随意识变化，对能量的操控能力极强。灵族是修炼天赋最高的种族之一。</li><li><strong>火族</strong>：由火焰能量凝聚而成的生命，身体温度极高，擅长火系法术，多生活在火山或高温区域。</li><li><strong>水族</strong>：由水之精华凝聚而成的生命，身体呈半透明液态，擅长水系法术与治愈，多生活在水域。</li><li><strong>风族</strong>：由风之精华凝聚而成的生命，身体轻盈如风，擅长风系法术与速度型战斗。</li><li><strong>雷族</strong>：由雷电能量凝聚而成的生命，身体蕴含强大电流，擅长雷系法术，攻击力极强。</li></ul><h3 id="三-机械构造族" tabindex="-1">（三）机械构造族 <a class="header-anchor" href="#三-机械构造族" aria-label="Permalink to &quot;（三）机械构造族&quot;">​</a></h3><ul><li><strong>机族</strong>：以精密机械构造为身体的种族，意识核心位于身体中央，具有强大的计算能力与物理防御力。</li><li><strong>数族</strong>：以数字与代码为生命本质的种族，存在于信息空间中，可以在数字世界中自由穿梭与操控数据。</li><li><strong>晶族</strong>：以晶体构造为身体的种族，晶体可以储存与转化能量，部分晶族具有能量放大与折射能力。</li></ul><h3 id="四-意识信息族" tabindex="-1">（四）意识信息族 <a class="header-anchor" href="#四-意识信息族" aria-label="Permalink to &quot;（四）意识信息族&quot;">​</a></h3><ul><li><strong>梦族</strong>：存在于梦境与意识空间中的生命，可以进入他人梦境，以意识交流为主要方式。</li><li><strong>影族</strong>：以影子形态存在的生命，可以依附于物体或生命体，具有隐匿与潜行能力。</li><li><strong>念族</strong>：以纯粹意念为存在形式的生命，可以用意念直接影响物质世界，精神力极强。</li></ul><h3 id="五-混合变异族" tabindex="-1">（五）混合变异族 <a class="header-anchor" href="#五-混合变异族" aria-label="Permalink to &quot;（五）混合变异族&quot;">​</a></h3><ul><li><strong>半兽族</strong>：人族与兽族的混合形态，兼具人族的智慧与兽族的体能。</li><li><strong>妖灵族</strong>：物质族与能量族的混合形态，同时具有物质身体与能量操控能力。</li><li><strong>人机族</strong>：人族与机械族的混合形态，身体部分机械化，兼具生物与机械优势。</li><li><strong>双魂体</strong>：一个身体中存在两个独立灵魂的特殊生命形态，其伦理问题详见《58-双魂伦理准则》。</li></ul><h2 id="四、万族共生关系" tabindex="-1">四、万族共生关系 <a class="header-anchor" href="#四、万族共生关系" aria-label="Permalink to &quot;四、万族共生关系&quot;">​</a></h2><p>锚点共生文明中的万族关系以&quot;共生&quot;为核心，具体表现为：</p><ol><li><strong>经济共生</strong>：各族发挥自身优势，在联产承包机制中承担不同角色，形成互补的经济协作网络。</li><li><strong>文化共生</strong>：各族文化传统得到尊重与保护，文化交流与互鉴促进文明整体繁荣。</li><li><strong>修炼共生</strong>：各族的修炼体系相互开放、相互借鉴，三百套本源修炼体系为各族提供平等的进化路径。</li><li><strong>政治共生</strong>：万族代表按比例参与锚点议事会，共同决定文明重大事务，确保各族的话语权。</li><li><strong>生态共生</strong>：各族与自然环境形成共生关系，不同种族的生理特性有助于维持生态系统的多样性与平衡。</li></ol><h2 id="五、种族冲突的预防与解决" tabindex="-1">五、种族冲突的预防与解决 <a class="header-anchor" href="#五、种族冲突的预防与解决" aria-label="Permalink to &quot;五、种族冲突的预防与解决&quot;">​</a></h2><p>尽管锚点共生文明确立了万族平等原则，但种族差异与历史矛盾仍可能引发冲突。国家建立以下机制预防与解决种族冲突：</p><ul><li><strong>种族事务部</strong>：专门负责协调万族关系，处理种族纠纷，促进种族交流。</li><li><strong>种族和解委员会</strong>：由各族代表组成，负责调解种族冲突，促进历史和解。</li><li><strong>反歧视法</strong>：禁止基于种族的歧视行为，对种族歧视行为依法惩处。</li><li><strong>文化交流计划</strong>：定期组织各族文化交流活动，增进相互理解与尊重。</li><li><strong>混合居住区</strong>：鼓励各族混合居住，打破种族隔离，促进日常交流。</li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>万族是衡元宙最宝贵的财富。生命形态的多样性不是分裂的根源，而是共生进化的动力。锚点共生文明通过确立万族平等原则、建立五大谱系分类、促进各族共生协作、预防与解决种族冲突，将万族从掠夺与战争的历史中解放出来，共同迈向共生进化的新纪元。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>51-人族定位与特质</li><li>52-异族分类与共生</li><li>05-万族共进基本纲领</li><li>40-共生宪法总纲</li></ul>',30)])])}const b=a(i,[["render",n]]);export{c as __pageData,b as default};
